// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("trinary.zig");
test "conversion and invalid digits" {
    try t.expectEqual(@as(u64, 26), m.toDecimal("222"));
    try t.expectEqual(@as(u64, 0), m.toDecimal("3"));
    try t.expectEqual(@as(u64, 0), m.toDecimal("-1"));
    try t.expectEqual(@as(u64, 0), m.toDecimal(""));
    try t.expectEqual(@as(u64, 3), m.toDecimal("0010"));
}
test "python test_valid_trinary1" {
    try t.expectEqual(@as(u64, 0), m.toDecimal("0"));
}
test "python test_valid_trinary2" {
    try t.expectEqual(@as(u64, 1), m.toDecimal("1"));
}
test "python test_valid_trinary3" {
    try t.expectEqual(@as(u64, 3), m.toDecimal("10"));
}
test "python test_valid_trinary4" {
    try t.expectEqual(@as(u64, 307), m.toDecimal("102101"));
}
test "python test_valid_trinary5" {
    try t.expectEqual(@as(u64, 242), m.toDecimal("22222"));
}
test "python test_valid_trinary6" {
